```tsx
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import type { CartItem, DeliveryAddress, AddressErrors } from './types';
import './CheckoutScreen.css';

// --- Minimal Telegram WebApp typing (only the surface we use) ---
interface TelegramWebApp {
  HapticFeedback?: {
    impactOccurred: (style: 'light' | 'medium' | 'heavy' | 'rigid' | 'soft') => void;
    notificationOccurred: (type: 'error' | 'success' | 'warning') => void;
  };
  BackButton?: {
    show: () => void;
    hide: () => void;
    onClick: (cb: () => void) => void;
    offClick: (cb: () => void) => void;
  };
}

declare global {
  interface Window {
    Telegram?: { WebApp?: TelegramWebApp };
  }
}

const DELIVERY_FEE = 4.99;
const FREE_DELIVERY_THRESHOLD = 50;
const CURRENCY = 'USD';

const formatCurrency = (value: number): string =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency: CURRENCY }).format(value);

const PHONE_REGEX = /^\+?[0-9\s-]{10,15}$/;

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};
  if (!address.fullName.trim()) errors.fullName = 'Enter your full name';
  if (!address.phone.trim()) errors.phone = 'Enter a phone number';
  else if (!PHONE_REGEX.test(address.phone.trim())) errors.phone = 'Enter a valid phone number';
  if (!address.city.trim()) errors.city = 'Enter a city';
  if (!address.street.trim()) errors.street = 'Enter a street';
  if (!address.house.trim()) errors.house = 'Enter a house/building number';
  return errors;
}

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  phone: '',
  city: '',
  street: '',
  house: '',
  apartment: '',
  comment: '',
};

interface CheckoutScreenProps {
  cartItems: CartItem[];
  initialAddress?: Partial<DeliveryAddress>;
  onBack: () => void;
  onPay: (address: DeliveryAddress, total: number) => Promise<void> | void;
}

function CartItemRow({ item }: { item: CartItem }) {
  return (
    <li className="cart-item">
      <img className="cart-item__image" src={item.imageUrl} alt="" />
      <div className="cart-item__info">
        <p className="cart-item__title">{item.title}</p>
        <p className="cart-item__meta">
          {item.quantity} × {formatCurrency(item.price)}
        </p>
      </div>
      <p className="cart-item__total">{formatCurrency(item.price * item.quantity)}</p>
    </li>
  );
}

export default function CheckoutScreen({
  cartItems,
  initialAddress,
  onBack,
  onPay,
}: CheckoutScreenProps) {
  const [address, setAddress] = useState<DeliveryAddress>({
    ...EMPTY_ADDRESS,
    ...initialAddress,
  });
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const deliveryFee = cartItems.length === 0 || subtotal >= FREE_DELIVERY_THRESHOLD ? 0 : DELIVERY_FEE;
  const total = subtotal + deliveryFee;
  const isCartEmpty = cartItems.length === 0;

  // Wire up Telegram's native back button to the same handler as the on-screen one.
  useEffect(() => {
    const webApp = window.Telegram?.WebApp;
    if (!webApp?.BackButton) return;
    webApp.BackButton.show();
    webApp.BackButton.onClick(onBack);
    return () => {
      webApp.BackButton?.offClick(onBack);
      webApp.BackButton?.hide();
    };
  }, [onBack]);

  const handleChange = useCallback(
    (field: keyof DeliveryAddress) =>
      (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        setAddress((prev) => ({ ...prev, [field]: e.target.value }));
      },
    []
  );

  const handleBlur = useCallback(
    (field: keyof DeliveryAddress) => () => {
      setTouched((prev) => ({ ...prev, [field]: true }));
      setErrors(validateAddress({ ...address }));
    },
    [address]
  );

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      phone: true,
      city: true,
      street: true,
      house: true,
      apartment: true,
      comment: true,
    });

    if (Object.keys(validationErrors).length > 0 || isCartEmpty) {
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      return;
    }

    setSubmitError(null);
    setIsSubmitting(true);
    try {
      await onPay(address, total);
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('success');
    } catch (err) {
      window.Telegram?.WebApp?.HapticFeedback?.notificationOccurred('error');
      setSubmitError(err instanceof Error ? err.message : 'Payment failed. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) => (touched[field] ? errors[field] : undefined);

  return (
    <div className="checkout">
      <header className="checkout__header">
        <button type="button" className="checkout__back" onClick={onBack} aria-label="Back to cart">
          <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
            <path d="M15 18l-6-6 6-6" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          <span>Cart</span>
        </button>
        <h1 className="checkout__title">Checkout</h1>
      </header>

      <main className="checkout__content">
        <section className="checkout__section" aria-labelledby="order-heading">
          <h2 id="order-heading" className="checkout__section-title">
            Your order
          </h2>

          {isCartEmpty ? (
            <p className="checkout__empty">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {cartItems.map((item) => (
                <CartItemRow key={item.id} item={item} />
              ))}
            </ul>
          )}

          <dl className="order-summary">
            <div className="order-summary__row">
              <dt>Subtotal</dt>
              <dd>{formatCurrency(subtotal)}</dd>
            </div>
            <div className="order-summary__row">
              <dt>Delivery</dt>
              <dd>{deliveryFee === 0 ? 'Free' : formatCurrency(deliveryFee)}</dd>
            </div>
            <div className="order-summary__row order-summary__row--total">
              <dt>Total</dt>
              <dd>{formatCurrency(total)}</dd>
            </div>
          </dl>
        </section>

        <form id="checkout-form" className="checkout__section" onSubmit={handleSubmit} noValidate>
          <h2 className="checkout__section-title">Delivery address</h2>

          <div className="field">
            <label htmlFor="fullName">Full name</label>
            <input
              id="fullName"
              type="text"
              autoComplete="name"
              value={address.fullName}
              onChange={handleChange('fullName')}
              onBlur={handleBlur('fullName')}
              aria-invalid={Boolean(fieldError('fullName'))}
              aria-describedby={fieldError('fullName') ? 'fullName-error' : undefined}
            />
            {fieldError('fullName') && (
              <p id="fullName-error" className="field__error">
                {fieldError('fullName')}
              </p>
            )}
          </div>

          <div className="field">
            <label htmlFor="phone">Phone number</label>
            <input
              id="phone"
              type="tel"
              autoComplete="tel"
              value={address.phone}
              onChange={handleChange('phone')}
              onBlur={handleBlur('phone')}
              aria-invalid={Boolean(fieldError('phone'))}
              aria-describedby={fieldError('phone') ? 'phone-error' : undefined}
            />
            {fieldError('phone') && (
              <p id="phone-error" className="field__error">
                {fieldError('phone')}
              </p>
            )}
          </div>

          <div className="field">
            <label htmlFor="city">City</label>
            <input
              id="city"
              type="text"
              autoComplete="address-level2"
              value={address.city}
              onChange={handleChange('city')}
              onBlur={handleBlur('city')}
              aria-invalid={Boolean(fieldError('city'))}
              aria-describedby={fieldError('city') ? 'city-error' : undefined}
            />
            {fieldError('city') && (
              <p id="city-error" className="field__error">
                {fieldError('city')}
              </p>
            )}
          </div>

          <div className="field-row">
            <div className="field">
              <label htmlFor="street">Street</label>
              <input
                id="street"
                type="text"
                autoComplete="address-line1"
                value={address.street}
                onChange={handleChange('street')}
                onBlur={handleBlur('street')}
                aria-invalid={Boolean(fieldError('street'))}
                aria-describedby={fieldError('street') ? 'street-error' : undefined}
              />
              {fieldError('street') && (
                <p id="street-error" className="field__error">
                  {fieldError('street')}
                </p>
              )}
            </div>

            <div className="field field--narrow">
              <label htmlFor="house">House</label>
              <input
                id="house"
                type="text"
                value={address.house}
                onChange={handleChange('house')}
                onBlur={handleBlur('house')}
                aria-invalid={Boolean(fieldError('house'))}
                aria-describedby={fieldError('house') ? 'house-error' : undefined}
              />
              {fieldError('house') && (
                <p id="house-error" className="field__error">
                  {fieldError('house')}
                </p>
              )}
            </div>
          </div>

          <div className="field">
            <label htmlFor="apartment">Apartment / unit (optional)</label>
            <input
              id="apartment"
              type="text"
              value={address.apartment}
              onChange={handleChange('apartment')}
              onBlur={handleBlur('apartment')}
            />
          </div>

          <div className="field">
            <label htmlFor="comment">Comment for courier (optional)</label>
            <textarea
              id="comment"
              rows={3}
              value={address.comment}
              onChange={handleChange('comment')}
              onBlur={handleBlur('comment')}
            />
          </div>
        </form>
      </main>

      <footer className="checkout__footer">
        {submitError && (
          <p className="checkout__submit-error" role="alert">
            {submitError}
          </p>
        )}
        <button
          type="submit"
          form="checkout-form"
          className="pay-button"
          disabled={isSubmitting || isCartEmpty}
        >
          {isSubmitting ? 'Processing…' : `Pay ${formatCurrency(total)}`}
        </button>
      </footer>
    </div>
  );
}
```

